{
  "name": "@smthrs/platform-browser",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "engine"
  },
  "description": "Browser implementations of Effect platform services backed by ZenFS and just-bash",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/flows/platform-browser"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "browser",
    "platform"
  ],
  "keywords": [
    "typescript",
    "effect",
    "browser",
    "platform"
  ],
  "engines": {
    "node": ">=26.4.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./BrowserChildProcessSpawner": "./src/BrowserChildProcessSpawner/index.ts",
    "./BrowserChildProcessSpawner/*": null,
    "./BrowserFileSystem": "./src/BrowserFileSystem/index.ts",
    "./BrowserFileSystem/*": null,
    "./internal/*": null,
    "./*/index": null,
    "./BrowserHost": "./src/BrowserHost.ts",
    "./BrowserServices": "./src/BrowserServices.ts",
    "./index": "./src/index.ts"
  },
  "imports": {
    "#access-handle-pool-vfs": {
      "types": "./src/internal/AccessHandlePoolVFS.d.ts",
      "default": "@journeyapps/wa-sqlite/src/examples/AccessHandlePoolVFS.js"
    }
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./BrowserChildProcessSpawner": {
        "import": {
          "types": "./dist/esm/BrowserChildProcessSpawner/index.d.ts",
          "default": "./dist/esm/BrowserChildProcessSpawner/index.js"
        },
        "require": {
          "types": "./dist/cjs/BrowserChildProcessSpawner/index.d.ts",
          "default": "./dist/cjs/BrowserChildProcessSpawner/index.js"
        }
      },
      "./BrowserChildProcessSpawner/*": null,
      "./BrowserFileSystem": {
        "import": {
          "types": "./dist/esm/BrowserFileSystem/index.d.ts",
          "default": "./dist/esm/BrowserFileSystem/index.js"
        },
        "require": {
          "types": "./dist/cjs/BrowserFileSystem/index.d.ts",
          "default": "./dist/cjs/BrowserFileSystem/index.js"
        }
      },
      "./BrowserFileSystem/*": null,
      "./internal/*": null,
      "./*/index": null,
      "./BrowserHost": {
        "import": {
          "types": "./dist/esm/BrowserHost.d.ts",
          "default": "./dist/esm/BrowserHost.js"
        },
        "require": {
          "types": "./dist/cjs/BrowserHost.d.ts",
          "default": "./dist/cjs/BrowserHost.js"
        }
      },
      "./BrowserServices": {
        "import": {
          "types": "./dist/esm/BrowserServices.d.ts",
          "default": "./dist/esm/BrowserServices.js"
        },
        "require": {
          "types": "./dist/cjs/BrowserServices.d.ts",
          "default": "./dist/cjs/BrowserServices.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../../repo-targets/scripts/circular.mjs",
    "test": "vitest",
    "coverage": "vitest --coverage",
    "bench": "vitest run --config vitest.bench.config.ts"
  },
  "dependencies": {
    "@journeyapps/wa-sqlite": "1.7.2",
    "@smthrs/artifacts": "1.0.0-rc.16",
    "@smthrs/crypto": "1.0.0-rc.16",
    "@smthrs/engine-store": "1.0.0-rc.16",
    "@smthrs/flow": "1.0.0-rc.16",
    "@smthrs/flows": "1.0.0-rc.16",
    "@smthrs/jj": "1.0.0-rc.16",
    "@smthrs/journal": "1.0.0-rc.16",
    "@smthrs/kernel": "1.0.0-rc.16",
    "@smthrs/plan": "1.0.0-rc.16",
    "@smthrs/run-store": "1.0.0-rc.16",
    "@smthrs/sandbox": "1.0.0-rc.16",
    "@smthrs/std": "1.0.0-rc.16",
    "@smthrs/database": "1.0.0-rc.16",
    "typescript": "5.9.3"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@effect/vitest": "4.0.5",
    "@eslint/js": "9.39.5",
    "@types/node": "26.4.1",
    "@vitest/coverage-v8": "5.0.0",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "madge": "8.0.0",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0",
    "@effect/platform-node": "4.0.5",
    "@smthrs/agent": "1.0.0-rc.16",
    "@smthrs/model": "1.0.0-rc.16",
    "@smthrs/registry": "1.0.0-rc.16",
    "playwright": "1.62.1",
    "@smthrs/observability": "1.0.0-rc.16",
    "@tanstack/browser-db-sqlite-persistence": "0.2.36",
    "@tanstack/db": "0.15.1",
    "@types/ws": "8.18.2",
    "ws": "8.22.0"
  },
  "peerDependencies": {
    "effect": "4.0.5"
  }
}

import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

/**
 * The benchmarks: timed runs of the engine over the Node suites' stores. They
 * print what they measure, assert nothing, and add nothing to coverage.
 */
export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    environment: "node",
    include: ["test/**/*.bench.{ts,vibe}"],
    testTimeout: 300_000
  }
})

import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

/**
 * The real-browser suites: Playwright's Chromium over real OPFS, Web Locks
 * and BroadcastChannel. They run bundles in the browser, so they add nothing
 * to the coverage the Node suites measure.
 */
export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    environment: "node",
    include: ["test/browser/**/*.test.{ts,vibe}"],
    testTimeout: 120_000,
    hookTimeout: 60_000
  }
})

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../../repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../../repo-targets/test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    setupFiles: ["test/fixtures/BrowserLocks.ts"],
    // The real-browser suites run under vitest.browser.config.ts.
    exclude: ["**/node_modules/**", "test/browser/**"],
    // The BrowserHost contract runs jj over the real flows_jj.wasm; the first
    // operation pays WebAssembly compilation, which can exceed the 5s default.
    testTimeout: 60_000,
    coverage: {
      enabled: true,
      provider: "v8",
      reportsDirectory: join(tmpdir(), `flows-platform-browser-coverage-${process.pid}`),
      include: ["src/**/*.{ts,vibe}"],
      thresholds: { branches: 100, functions: 100, lines: 100, statements: 100 }
    }
  }
})
